# Final attempt: Look for patterns containing BOTH colors 7 and 8 (or the two main fg colors)
from collections import Counter

demo1_lines = """8 7 2 2 7 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2
2 7 7 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2
7 7 2 3 3 3 3 3 3 3 3 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2"""

demo1_grid = [[int(x) for x in line.split()] for line in demo1_lines.strip().split('\n')]

bg = 2

def get_pattern_with_multiple_fg_colors(grid):
    """Find exact subgrids with at least 2 distinct non-bg colors"""
    h, w = len(grid), len(grid[0])

    # Try sizes from smallest to largest
    results = []
    for size_h in range(2, min(h+1, 4)):
        for size_w in range(2, min(w+1, 4)):
            for i in range(h - size_h + 1):
                for j in range(w - size_w + 1):
                    pat = tuple(tuple(grid[i+di][j+dj] for dj in range(size_w)) for di in range(size_h))
                    # Get set of colors excluding bg
                    colors_in_pat = set(c for rows in pat for c in rows)
                    fg_colors = colors_in_pat - {bg}
                    if len(fg_colors) >= 2:
                        results.append((size_h, size_w, pat, list(fg_colors)))

    return results

patterns_with_multi_fg = get_pattern_with_multiple_fg_colors(demo1_grid)

print(f"Patterns with 2+ distinct foreground colors: {len(patterns_with_multi_fg)}")
for p in patterns_with_multi_fg[:20]:
    print(f"{p}")

# Hmm, none appear more than once in Demo 1. What if we count by SHAPE instead?

def get_normalized_patterns(grid):
    """Count shapes ignoring actual color values"""
    h, w = len(grid), len(grid[0])
    shape_counter = Counter()

    for size_h in range(2, min(h+1, 6)):
        for size_w in range(2, min(w+1, 6)):
            for i in range(h - size_h + 1):
                for j in range(w - size_w + 1):
                    # Extract shape (just which cells have fg vs bg)
                    shape = tuple('1' if grid[i+di][j+dj] != bg else '0'
                                 for di in range(size_h) for dj in range(size_w))

                    # Only count if there are at least 2 different fg colors present
                    colors = set(grid[i+di][j+dj] for di in range(size_h) for dj in range(size_w) 
                                if grid[i+di][j+dj] != bg)
                    if len(colors) >= 2:
                        shape_counter[shape] += 1

    return shape_counter

shape_counts = get_normalized_patterns(demo1_grid)
print("\nShapes with 2+ fg colors, sorted by count:")
